'use client'
import { useEffect, useState } from 'react'
import Footer from '../components/Footer'
import PersonAvatar from '../components/PersonAvatar'
import RecordRow from '../components/report/RecordRow'
import TopCard from '../components/report/TopCard'
import Disclosure from '../components/ui/Disclosure'
import Icon from '../components/ui/Icon'
import Segmented from '../components/ui/Segmented'
import { ButtonLink } from '../components/ui/Button'
import { missingCards, profileText } from '../presenters/report'
import { caseLine, householdLine, neverHappened, recordDetail, sources, summary, themes, topActions, topCards } from '../presenters/reportView'
import '../components/report/report.css'
import './ReportPage.css'

// The personal report (SPEC A5), a view: presenters/reportView.js decides what it says. It answers three questions in
// plain words (what changed here, is it real, does it matter for us) with at most two numbers per record; the trend
// tests, months, events, maps and comparisons are one click away on the Look closer pages.
// Without a report prop it shows the sample at the bottom (fake numbers, layout only).
const PERIODS = [10, 15, 20, 25]   // must match period_options in data_pipeline/config/thresholds.json

export default function ReportPage({ report = SAMPLE_REPORT, avatarAssets, focus = null, question = '', period = 25, onPeriodChange, updating = false, failed = '', onRetry, onHome, lookCloser, household = 'own' }) {
  const [openKey, setOpenKey] = useState(focus && report?.factors?.[focus]?.available ? focus : null)
  const [allActions, setAllActions] = useState(false)
  const factors = report?.factors || {}
  const place = report?.location?.name || 'Your selected location'
  const placeName = place.split(',')[0]
  const years = report?.period?.length === 2 ? `${report.period[0]}–${report.period[1]}` : ''
  const head = summary(report)
  const top = topCards(report)
  const groups = themes(report)
  const actions = topActions(report, Infinity)
  const shownActions = allActions ? actions : actions.slice(0, 3)
  const missing = missingCards(report)

  // When the report replaces the loading screen, focus falls to <body>: give it to the heading (screen readers start here)
  useEffect(() => {
    if (!document.activeElement || document.activeElement === document.body) document.getElementById('report-title')?.focus({ preventScroll: true })
  }, [])

  const toggle = (key) => setOpenKey((k) => (k === key ? null : key))
  // From a card or a chip: open the record's row and bring it into view (smoothly unless motion is reduced)
  function openRecord(key) {
    setOpenKey(key)
    requestAnimationFrame(() => {
      const row = document.getElementById(`rec-${key}`)
      row?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' })
      row?.querySelector('.rp-row-btn')?.focus({ preventScroll: true })   // keyboard users land on what opened
    })
  }

  return (
    <div className="report-page">
      {/* the answer (hero) is inside <main>, so "Skip to content" lands on it (round 3) */}
      <main id="main" aria-busy={updating}>
      <header className="report-hero">
        <div className="report-hero-inner">
          <div className="hero-place">
            {onHome && (
              <button type="button" className="report-home" onClick={onHome}>
                <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5M11 6l-6 6 6 6" /></svg>
                Change place
              </button>
            )}
            <p className="hero-eyebrow">Climate trend report{years && `, ${years}`}</p>
            <h1 id="report-title" tabIndex={-1}>{placeName}</h1>
            <p className="hero-sub">{place}</p>
            {onPeriodChange && (
              <div className="periods">
                <Segmented legend="Years analyzed" name="report-years" tone="dark" size="sm" value={period} onChange={onPeriodChange}
                  options={PERIODS.map((p) => ({ value: p, label: `${p} years` }))} />
                <span className="periods-status" aria-live="polite">{updating ? 'Updating…' : ''}</span>
                {failed && (
                  <p className="rp-failed" role="alert">
                    Couldn’t load {period} years: {failed} Still showing {years}.{' '}
                    {onRetry && <button type="button" onClick={onRetry}>Try again</button>}
                  </p>
                )}
              </div>
            )}
          </div>
          <section className="hero-verdict" aria-labelledby="headline-title">
            <p className="hero-eyebrow">What changed here</p>
            <h2 id="headline-title" className="rp-sentence">{head.sentence}</h2>
            {head.chips.length > 0 && (
              <ul className="rp-chips" aria-label="The records that clearly changed">
                {head.chips.map((c) => (
                  <li key={c.key}>
                    <button type="button" className={`rp-chip is-${c.verdict.tone}`} onClick={() => openRecord(c.key)}>
                      <Icon name={c.verdict.arrow} size={16} />{c.name}<small>{c.verdict.tone === 'up' ? 'worse' : 'better'}</small>
                    </button>
                  </li>
                ))}
              </ul>
            )}
            {head.rest > 0 && <p className="rp-rest">{head.rest} more {head.rest === 1 ? 'record shows' : 'records show'} no clear change yet.</p>}
          </section>
          <section className="hero-profile" aria-labelledby="profile-title">
            <PersonAvatar ageGroup={report?.user?.age_groups?.[0] || report?.user?.age_group} assets={avatarAssets} />
            <div>
              <p className="hero-eyebrow">Who lives here</p>
              <h2 id="profile-title">{household === 'general' ? 'A general household' : household === 'example' ? `Example household: ${profileText(report?.user)}` : profileText(report?.user)}</h2>
              {household === 'general' && <a className="hero-tell" href="/">Tell us who lives here</a>}
            </div>
          </section>
        </div>
      </header>

      <div className="report rp">
        {question && (
          <section className="case" aria-labelledby="case-title">
            <p className="eyebrow">Case file</p>
            <h2 id="case-title">{question}</h2>
            <p>{caseLine(report, focus)}</p>
          </section>
        )}
        {report?._WARNING && <p className="note">Sample report: illustrative numbers for layout only.</p>}

        {top.length > 0 && (
          <section className="rp-section" aria-labelledby="top-title">
            <h2 id="top-title">Most important for you</h2>
            <p className="note">{household === 'general' ? 'These start from a general household. Tell us who lives here to put your own priorities first.' : householdLine(report, top)}</p>
            <div className="rp-tops">
              {top.map((t) => <TopCard key={t.key} detail={recordDetail(factors[t.key])} onOpen={openRecord} mine={household === 'own'} />)}
            </div>
          </section>
        )}

        <section className="rp-section" aria-labelledby="all-title">
          <h2 id="all-title">Everything we checked</h2>
          <p className="note">Each record compares the first five years with the last five. Open one to see every year.</p>
          <div className="rp-themes">
            {groups.map((g) => (
              <section key={g.id} className="rp-theme" aria-labelledby={`theme-${g.id}`}>
                <h3 id={`theme-${g.id}`}><Icon name={g.icon} size={16} />{g.label}</h3>
                <ul className="rp-rows">
                  {g.rows.map((row) => (
                    <RecordRow key={row.key} row={row} detail={recordDetail(factors[row.key])} open={openKey === row.key}
                      onToggle={toggle} lookCloser={lookCloser} />
                  ))}
                </ul>
              </section>
            ))}
          </div>
          {neverHappened(report) && <p className="rp-missing">{neverHappened(report)}</p>}
          {missing.length > 0 && <p className="rp-missing">Not available here: {missing.join('; ')}.</p>}
        </section>

        {actions.length > 0 && (
          <section className="rp-section panel actions" aria-labelledby="actions-title">
            <h2 id="actions-title">What people do about it</h2>
            {shownActions.map((item) => (
              <article className="action" key={item.factor}>
                <h3>{item.label}</h3>
                <ul>{item.actions?.map((action) => <li key={action}>{action}</li>)}</ul>
                {item.source?.url && <a href={item.source.url} target="_blank" rel="noreferrer">{item.source.name}</a>}
              </article>
            ))}
            {actions.length > 3 && !allActions && (
              <button type="button" className="link-button" onClick={() => setAllActions(true)}>Show all</button>
            )}
          </section>
        )}

        <section className="rp-section rp-how" aria-labelledby="how-title">
          <Disclosure summary={<span id="how-title">How we know</span>}>
            <p>Every number here comes from NASA (and NOAA) records for {years || 'the years analyzed'}. For each record we compare the average of the
              first five years with the last five, and we call a change clear only when it is too steady across the years to be
              chance. Most numbers are averages over a square of about 50 km around this place, so they describe the area, not one street.</p>
            <ul>{sources(report).map((s) => <li key={s}>{s}</li>)}</ul>
            <p><ButtonLink href="/about" variant="ghost" size="sm" icon="info">About the data and the tests</ButtonLink></p>
          </Disclosure>
        </section>
      </div>
      </main>
      <Footer />
    </div>
  )
}

